package com.abluepoint.summer.sample.delegation;

import com.abluepoint.summer.sample.mcpauthorization.HumanApprovalBinding;
import com.abluepoint.summer.common.error.SummerException;
import com.abluepoint.summer.sample.enterprise.DirectoryErrorCode;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;
import org.springframework.stereotype.Service;
import java.time.Instant;
import java.util.*;

@Service final class DelegationService {
    private final com.abluepoint.summer.sample.resource.BusinessResourceAccess business;
    DelegationService(com.abluepoint.summer.sample.resource.BusinessResourceAccess business) { this.business=business; }

    private static final String ENTERPRISE="ent-acme";
    private final Map<String,Grant> grants=new LinkedHashMap<>(); private final Map<String,Approval> approvals=new LinkedHashMap<>(); private final Map<String,Receipt> receipts=new HashMap<>(); private final Map<String,List<DelegationAuditView>> audit=new HashMap<>();
    synchronized DelegationGrantView create(String enterpriseId,String agentId,DelegationCreateRequest r,String key,String rid,Authentication a){ requireEnt(enterpriseId,a,"enterprise.agents.delegations.write"); key(key); Receipt p=receipts.get(enterpriseId+":"+key); String fp=fp(r); if(p!=null)return replay(p,fp); if(r==null||blank(r.scopeType())||blank(r.mcpServerId())||r.toolPatterns()==null||r.toolPatterns().isEmpty())throw SummerException.withMessage(DelegationErrorCode.INVALID, "scopeType, mcpServerId and toolPatterns are required"); Grant parent=r.parentGrantId()==null?null:grant(r.parentGrantId()); int depth=0; if(parent!=null){if(!parent.enterpriseId.equals(enterpriseId)||!parent.agentId.equals(agentId)||!parent.allowRedelegation)throw SummerException.withMessage(DelegationErrorCode.INVALID, "Parent delegation does not allow redelegation"); depth=parent.depth+1; if(depth>parent.maxDepth)throw SummerException.withMessage(DelegationErrorCode.INVALID, "Delegation depth exceeded"); if(r.maxDelegationDepth()!=null&&r.maxDelegationDepth()>parent.maxDepth)throw SummerException.withMessage(DelegationErrorCode.INVALID, "Delegation max depth cannot expand"); if(!subset(r.toolPatterns(),parent.tools)||!subset(r.capabilityCodes()==null?List.of():r.capabilityCodes(),parent.capabilities))throw SummerException.withMessage(DelegationErrorCode.INVALID, "Child delegation expands scope"); if(r.maxRiskLevel()!=null&&risk(r.maxRiskLevel())>risk(parent.maxRisk))throw SummerException.withMessage(DelegationErrorCode.INVALID, "Child delegation expands risk"); if(r.expiresInSeconds()!=null&&r.expiresInSeconds()>Math.max(1,parent.expiresAt.getEpochSecond()-Instant.now().getEpochSecond()))throw SummerException.withMessage(DelegationErrorCode.INVALID, "Child delegation exceeds parent lifetime"); }
        long ttl=r.expiresInSeconds()==null?3600:Math.max(60,Math.min(86400,r.expiresInSeconds())); Instant now=Instant.now(); Grant g=new Grant("dgrant-"+UUID.randomUUID().toString().substring(0,8),enterpriseId,a.getName(),agentId,r.parentGrantId(),depth,r.scopeType(),r.mcpServerId(),List.copyOf(r.toolPatterns()),r.resourcePatterns()==null?List.of():List.copyOf(r.resourcePatterns()),r.capabilityCodes()==null?List.of():List.copyOf(r.capabilityCodes()),r.maxRiskLevel()==null?"MEDIUM":r.maxRiskLevel(),Boolean.TRUE.equals(r.allowRedelegation()),r.maxDelegationDepth()==null?0:r.maxDelegationDepth(),now,now.plusSeconds(ttl),"ACTIVE",1); grants.put(g.id,g); DelegationGrantView out=view(g); receipts.put(enterpriseId+":"+key,new Receipt(fp,out)); log(g.id,null,enterpriseId,"DELEGATION_CREATED",a); return out; }
    synchronized List<DelegationGrantView> list(String e,String agent,Authentication a){requireEnt(e,a,"enterprise.agents.delegations.read","enterprise.agents.delegations.write"); return grants.values().stream().filter(g->e.equals(g.enterpriseId)&&agent.equals(g.agentId)).map(this::view).toList();}
    synchronized DelegationGrantView revoke(String e,String id,String key,String rid,Authentication a){requireEnt(e,a,"enterprise.agents.delegations.write"); key(key); Grant g=grant(id); if(!e.equals(g.enterpriseId))throw new AccessDeniedException("Enterprise context denied"); g.status="REVOKED"; DelegationGrantView out=view(g); receipts.put(e+":"+key,new Receipt(fp(id),out)); log(id,null,e,"DELEGATION_REVOKED",a); return out;}
    synchronized ApprovalView createApproval(ApprovalCreateRequest r,String key,String rid,Authentication a){ if(r==null||blank(r.enterpriseId()))throw SummerException.withMessage(DelegationErrorCode.INVALID, "enterpriseId is required"); requireApprovalCreate(r.enterpriseId(),a); key(key); Receipt p=receipts.get(r.enterpriseId()+":"+key); String fp=fp(r); if(p!=null)return replay(p,fp); if(blank(r.mcpServerId())||blank(r.toolId())||blank(r.requestDigest()))throw SummerException.withMessage(DelegationErrorCode.INVALID, "mcpServerId, toolId and requestDigest are required"); Instant now=Instant.now(); long ttl=r.expiresInSeconds()==null?900:Math.max(60,Math.min(3600,r.expiresInSeconds())); Approval ap=new Approval("approval-"+UUID.randomUUID().toString().substring(0,8),r.enterpriseId(),a.getName(),r.agentId(),r.agentInstanceId(),r.approverPrincipalId(),r.mcpServerId(),r.toolId(),r.requestDigest(),r.approvalScope()==null?"ONE_CALL":r.approvalScope(),"PENDING",now.plusSeconds(ttl),null,null,null,1); approvals.put(ap.id,ap); ApprovalView out=view(ap); receipts.put(r.enterpriseId()+":"+key,new Receipt(fp,out)); log(null,ap.id,r.enterpriseId(),"APPROVAL_CREATED",a); return out; }
    synchronized String createBoundApproval(HumanApprovalBinding b){
        Instant now=Instant.now();
        String id="approval-"+UUID.randomUUID().toString().substring(0,8);
        Approval ap=new Approval(id,b.enterpriseId(),b.initiatorPrincipalId(),b.actorPrincipalId(),b.actorInstanceId(),null,b.connectionServiceId(),b.toolId(),b.argumentsDigest(),"ONE_CALL","PENDING",now.plusSeconds(900),null,null,null,1,binding(b));
        approvals.put(id,ap); log(null,id,b.enterpriseId(),"APPROVAL_CREATED",null); return id;
    }
    synchronized boolean consumeBoundApproval(String id,HumanApprovalBinding b){
        Approval ap=approvals.get(id); if(ap==null||ap.executionBinding==null||!ap.executionBinding.equals(binding(b)))return false;
        expire(ap); if(!"APPROVED".equals(ap.status)||ap.consumedAt!=null)return false;
        ap.consumedAt=Instant.now(); ap.status="CONSUMED"; ap.version++; log(null,id,ap.enterpriseId,"APPROVAL_CONSUMED",null); return true;
    }
    synchronized ApprovalView decide(String id,String action,String key,Authentication a){ Approval ap=approval(id); if("APPROVE".equals(action)||"REJECT".equals(action))requireEnt(ap.enterpriseId,a,"enterprise.mcp.approvals.approve"); else requireEnt(ap.enterpriseId,a,"enterprise.mcp.approvals.write"); key(key); expire(ap); if(!"PENDING".equals(ap.status))throw SummerException.withMessage(DelegationErrorCode.CONFLICT, "Approval is not pending"); ap.status=action.equals("APPROVE")?"APPROVED":action.equals("REJECT")?"REJECTED":"WITHDRAWN"; if("APPROVE".equals(action)){ap.approvedBy=a.getName();ap.approvedAt=Instant.now();} ap.version++; log(null,id,ap.enterpriseId,"APPROVAL_"+ap.status,a); return view(ap); }
    synchronized ApprovalView recheck(String id,Authentication a){Approval ap=approval(id);requireEnt(ap.enterpriseId,a,"enterprise.mcp.approvals.approve","enterprise.mcp.approvals.write");expire(ap);return view(ap);}
    synchronized List<DelegationAuditView> audit(String e,String id,Authentication a){requireEnt(e,a,"enterprise.agents.delegations.read","enterprise.mcp.approvals.approve"); return List.copyOf(audit.getOrDefault(e+":"+id,List.of()));}
    private void expire(Approval a){if("PENDING".equals(a.status)&&Instant.now().isAfter(a.expiresAt)){a.status="EXPIRED";a.version++;log(null,a.id,a.enterpriseId,"APPROVAL_EXPIRED",null);}}
    private Approval approval(String id){Approval a=approvals.get(id);if(a==null)throw SummerException.withMessage(DelegationErrorCode.CONFLICT, "Approval not found");return a;} private Grant grant(String id){Grant g=grants.get(id);if(g==null)throw SummerException.withMessage(DelegationErrorCode.CONFLICT, "Delegation not found");return g;}
    private void requireApprovalCreate(String enterprise,Authentication actor) {
        if(!ENTERPRISE.equals(enterprise)) throw new AccessDeniedException("Delegation capability denied");
        try {
            if(business.requireHttp(com.abluepoint.summer.security.authorization.ResourceAuthorization.Domain.enterprise(enterprise),
                    actor,"POST","/internal/v1/mcp/approvals","enterprise.mcp.approvals.write")) return;
        } catch(AccessDeniedException denied) {throw new AccessDeniedException("Delegation capability denied",denied);}
        requireEnt(enterprise,actor,"enterprise.mcp.approvals.write");
    }
    private void requireEnt(String e,Authentication a,String... caps){if(!ENTERPRISE.equals(e))throw new AccessDeniedException("Delegation capability denied");if(business.requirePreservingDenial(com.abluepoint.summer.security.authorization.ResourceAuthorization.Domain.enterprise(e),a,"Delegation capability denied",caps))return;if(!ENTERPRISE.equals(e)||!(a instanceof JwtAuthenticationToken j)||!active(j,e)||!cap(j,e,caps)||Arrays.stream(caps).noneMatch(c->j.getAuthorities().stream().anyMatch(x->("SCOPE_"+c).equals(x.getAuthority()))))throw new AccessDeniedException("Delegation capability denied");}
    private boolean active(JwtAuthenticationToken j,String e){Object v=j.getToken().getClaims().get("enterprise_memberships");return v instanceof Collection<?> c&&c.stream().filter(Map.class::isInstance).map(x->(Map<?,?>)x).anyMatch(m->e.equals(String.valueOf(m.getOrDefault("enterpriseId",m.get("enterprise_id"))))&&"ACTIVE".equalsIgnoreCase(String.valueOf(m.getOrDefault("status",m.get("membership_status")))));}
    private boolean cap(JwtAuthenticationToken j,String e,String... cs){Object v=j.getToken().getClaims().get("enterprise_capabilities");if(!(v instanceof Map<?,?>m))return false;Object g=m.get(e);return g instanceof Collection<?> c&&Arrays.stream(cs).anyMatch(x->c.stream().map(String::valueOf).anyMatch(x::equals));}
    private static boolean subset(List<String>a,List<String>b){return b==null||a.stream().allMatch(x->b.stream().anyMatch(y->y.equals(x)||y.equals("*")));} private static int risk(String r){return Map.of("LOW",1,"MEDIUM",2,"HIGH",3,"CRITICAL",4).getOrDefault(r.toUpperCase(),99);} private static boolean blank(String s){return s==null||s.isBlank();} private static void key(String k){if(blank(k))throw SummerException.withMessage(DelegationErrorCode.INVALID, "Idempotency-Key is required");} private static String fp(Object o){return Integer.toHexString(Objects.hashCode(String.valueOf(o)));}
    @SuppressWarnings("unchecked")private<T>T replay(Receipt p,String f){if(!p.fp.equals(f))throw SummerException.withMessage(DirectoryErrorCode.IDEMPOTENCY_CONFLICT, "Idempotency key reused");return(T)p.result;}
    private void log(String d,String ap,String e,String action,Authentication a){audit.computeIfAbsent(e+":"+(d==null?ap:d),x->new ArrayList<>()).add(new DelegationAuditView(action,d,ap,e,a==null?"":a.getName(),Instant.now()));}
    private DelegationGrantView view(Grant g){return new DelegationGrantView(g.id,g.enterpriseId,g.delegator,g.agentId,g.parentId,g.depth,g.scopeType,g.server,g.tools,g.resources,g.capabilities,g.maxRisk,g.allowRedelegation,g.maxDepth,g.validFrom,g.expiresAt,g.status,g.version);} private ApprovalView view(Approval a){return new ApprovalView(a.id,a.enterpriseId,a.requestedBy,a.agentId,a.instanceId,a.approver,a.server,a.tool,a.digest,a.scope,a.status,a.expiresAt,a.approvedAt,a.consumedAt,a.approvedBy,a.version);}
    private static String binding(HumanApprovalBinding b){return String.valueOf(b);}
    private record Receipt(String fp,Object result){} private static final class Grant{final String id,enterpriseId,delegator,agentId,parentId,scopeType,server,maxRisk;final int depth,maxDepth;final List<String> tools,resources,capabilities;final boolean allowRedelegation;final Instant validFrom,expiresAt;String status;long version;Grant(String i,String e,String d,String a,String p,int de,String s,String se,List<String>t,List<String>r,List<String>c,String mr,boolean ar,int md,Instant vf,Instant ex,String st,long v){id=i;enterpriseId=e;delegator=d;agentId=a;parentId=p;depth=de;scopeType=s;server=se;tools=t;resources=r;capabilities=c;maxRisk=mr;allowRedelegation=ar;maxDepth=md;validFrom=vf;expiresAt=ex;status=st;version=v;}} private static final class Approval{final String id,enterpriseId,requestedBy,agentId,instanceId,approver,server,tool,digest,scope,executionBinding;String status,approvedBy;final Instant expiresAt;Instant approvedAt,consumedAt;long version;Approval(String i,String e,String r,String ag,String in,String ap,String s,String t,String d,String sc,String st,Instant ex,Instant aa,Instant ca,String ab,long v){this(i,e,r,ag,in,ap,s,t,d,sc,st,ex,aa,ca,ab,v,null);} Approval(String i,String e,String r,String ag,String in,String ap,String s,String t,String d,String sc,String st,Instant ex,Instant aa,Instant ca,String ab,long v,String eb){id=i;enterpriseId=e;requestedBy=r;agentId=ag;instanceId=in;approver=ap;server=s;tool=t;digest=d;scope=sc;status=st;expiresAt=ex;approvedAt=aa;consumedAt=ca;approvedBy=ab;version=v;executionBinding=eb;}}
}
